import "package:flutter/material.dart"; import "../models/user.dart"; import "../services/auth_service.dart"; class AuthProvider extends ChangeNotifier { final AuthService _authService = AuthService(); User? _user; bool _isLoading = false; String? _error; User? get user => _user; bool get isLoading => _isLoading; String? get error => _error; bool get isAuthenticated => _user != null; Future<bool> login(String email, String password) async { _isLoading = true; _error = null; notifyListeners(); try { final response = await _authService.login(email: email, password: password); _user = User.fromJson(response["data"]); _isLoading = false; notifyListeners(); return true; } catch (e) { _error = e.toString(); _isLoading = false; notifyListeners(); return false; } } Future<bool> register({required String name, required String email, required String password, required String role, String? mobile, String? reraId}) async { _isLoading = true; _error = null; notifyListeners(); try { final response = await _authService.register(name: name, email: email, password: password, role: role, mobile: mobile, reraId: reraId); _user = User.fromJson(response["data"]); _isLoading = false; notifyListeners(); return true; } catch (e) { _error = e.toString(); _isLoading = false; notifyListeners(); return false; } } Future<void> logout() async { await _authService.logout(); _user = null; notifyListeners(); } Future<void> loadUser() async { try { _user = await _authService.getMe(); notifyListeners(); } catch (e) { _error = e.toString(); notifyListeners(); } } void clearError() { _error = null; notifyListeners(); } }
